   if(saved?.schema!==1||saved.owner!==owner||!reportPending(saved)||!input||!/^\d{4}-\d{2}-\d{2}$/.test(input.date||'')||!/^[\w-]{36}$/.test(input.requestId||'')||!Number.isSafeInteger(input.revision)||!Array.isArray(input.recipients)||typeof input.subject!=='string'||typeof input.time!=='string')return;
