 function shell(s){s.root.innerHTML='<div class="settings-page"><div class="page-heading"><h2>'+esc(s.page)+'</h2>'+(s.page==='System Config'?'<span class="access-label">'+(s.ctx.profile.user.admin?'Admin':'SMC · View only')+'</span>':'')+'</div><p data-settings-message role="status" aria-live="polite"></p><p data-settings-progress role="status" aria-live="polite" hidden><span class="ops-spinner" aria-hidden="true"></span> <span data-settings-progress-label></span></p><div data-settings-retry></div><div data-settings-body></div></div>';}
 function retry(s){const box=q(s,'[data-settings-retry]');box.querySelector('[data-pending-request]')?.remove();box.querySelector('[data-pending-explanation]')?.remove();if(!pending||pending.owner!==s.owner||pending.page!==s.page)return;box.replaceChildren();if(reportPending(pending)){const text=document.createElement('p');text.dataset.pendingExplanation='';text.textContent='A report-settings save needs confirmation. Check saved settings to retry the exact same request; this does not send a report.'+(s.storageFailed?' Keep this page open; this browser could not store the pending save for recovery after a reload.':'');box.append(text);}const button=document.createElement('button');button.className='primary';button.dataset.pendingRequest='';button.textContent=reportPending(pending)?'Check saved settings':'Retry the same request';button.disabled=s.busy;button.onclick=()=>save(s);box.append(button);q(s,'[data-settings-body]').inert=true;}
