  catch(e){const auth=e.status===401||e.status===403,definitive=e.status>=400&&e.status<500&&![408,429].includes(e.status)&&!(report&&wasUncertain&&auth);if(definitive)clearPending(request);else{request.uncertain=true;storePending(s,request);}if(!live(s))return;if(e.status===409){await load(s,true);message(s,'Another user changed these records. Your changes are retained. Review them and save again.',true);}else if(auth){s.data=null;s.draft=null;s.dirty=false;s.readFailed=true;q(s,'[data-settings-body]').replaceChildren();message(s,(e.message||'Sign in again.')+(report&&pending===request?' Your pending settings save is retained for this account.':''),true);}else message(s,(e.message||'The request could not be confirmed.')+(!report&&pending?' Retry the same request to confirm it.':''),true);}
