  host.innerHTML='<h3>'+esc(options.title)+'</h3><p>'+esc(options.intro)+'</p><p class="hint">'+esc(options.source)+'</p><div class="settings-exclusion-step"><h4>1. Add wildcard patterns</h4><div class="settings-inline"><label>Wildcard pattern<input data-rule-pattern placeholder="For example: PD* or BLK*" maxlength="160"></label><button type="button" data-add-pattern>Add exclusion pattern</button></div><p class="hint">* matches any characters. PD* includes PD and PD (ART). BLK* includes all subjects starting with BLK. Other punctuation is literal.</p><div data-rule-chips class="settings-rule-chips"></div></div><div class="settings-exclusion-step"><h4>2. Select additional specific subjects</h4><p class="hint">Choose subjects not already matched by the wildcard patterns above.</p><label>Find a subject<input data-subject-search type="search" autocomplete="off" placeholder="Search remaining subjects" aria-controls="'+options.id+'"></label><div id="'+options.id+'" class="settings-subject-options" data-subject-options></div><div data-exact-rule-chips class="settings-rule-chips"></div></div><div data-rule-preview class="settings-exclusion-result" aria-live="polite"></div><p class="hint">'+esc(options.note)+'</p>';
